local Json = require("src.link.Json")
local MysteryGift = require("src.core.game3.mystery_gift")
local Bag = require("src.core.game3.bag")
local Schema = require("src.core.game3.save_schema_firered")
MysteryGift.GIFT_PUBKEY = FIXTURE_PUB

local FEEDS = { frlg = FEED_FRLG, rse = FEED_RSE, rs = FEED_RS }
local FAMILY_GAMES = { frlg = { "firered", "leafgreen" }, rse = { "emerald" }, rs = { "ruby", "sapphire" } }

local function raw(family)
  return Json.decode(Json.decode(FEEDS[family]).payload)
end

local function session(version)
  local s = Schema.newGame({ rngSeed = 0x99 })
  s.version = version
  s.store = { flags = {}, vars = {} }
  s.bag = Bag.new()
  s.party = {}
  return s
end

print("[test] 1. Every card preset reaches exactly the games it lists")
for _, family in ipairs({ "frlg", "rse" }) do
  for _, row in ipairs(raw(family).cards) do
    for _, game in ipairs(FAMILY_GAMES[family]) do
      local list = assert(MysteryGift.verifyFeed(Json.decode(FEEDS[family]), family, game))
      local found = false
      for _, e in ipairs(list.cards) do if e.key == row.key then found = true end end
      eq(found, MysteryGift.offeredIn(row.versions, game), row.key .. " on " .. game)
    end
  end
end

print("[test] 2. Every non-mon card preset delivers on its own game")
for _, family in ipairs({ "frlg", "rse" }) do
  for _, row in ipairs(raw(family).cards) do
    local game = row.versions[1]
    local s = session(game)
    local list = MysteryGift.verifyFeed(Json.decode(FEEDS[family]), family, game)
    local entry
    for _, e in ipairs(list.cards) do if e.key == row.key then entry = e end end
    check(entry ~= nil, row.key .. " parses on " .. game)
    if entry then
      check(MysteryGift.receiveCard(s, entry.card), row.key .. " is saved")
      local kind = entry.card.gift.kind
      local script = MysteryGift.ramScriptId(s, entry.card)
      if script then
        -- pokeemerald/src/script.c:441 GetSavedRamScriptIfValid
        local known = { eon = true, aurora = true, mystic = true, oldSeaMap = true, surfPichu = true,
          stampCard = true, battleCard = true, alteringCave = true }
        check(known[script] == true, row.key .. " runs the Emerald ROM gift script " .. tostring(script))
      elseif kind == "item" and not entry.card.gift.requireStat then
        eq(MysteryGift.deliverGift(s, entry.card), MysteryGift.DELIVER_GIVEN, row.key .. " is handed over")
        check(Bag.has(s.bag, entry.card.gift.item, 1), row.key .. " lands in the bag")
      elseif kind == "var" then
        eq(MysteryGift.deliverGift(s, entry.card), MysteryGift.DELIVER_GIVEN, row.key .. " bumps its variable")
      elseif kind == "none" or entry.card.gift.requireStat then
        eq(MysteryGift.deliverGift(s, entry.card), MysteryGift.DELIVER_NOTHING, row.key .. " is a card only until earned")
      end
    end
  end
end

print("[test] 3. Event Pokémon cards follow their PKHeX templates")
local bit = require("bit")
local function shinyValue(mon)
  local p = mon.personality % 4294967296
  return bit.bxor(bit.bxor(mon.otId % 65536, (mon.otSecretId or 0) % 65536),
    bit.bxor(math.floor(p / 65536), p % 65536))
end
if not romBundle then
  print("[skip] no FireRed cache for the species data")
else
  local Ribbons = require("src.core.game3.rse.ribbons")
  for _, family in ipairs({ "frlg", "rse" }) do
    for _, row in ipairs(raw(family).cards) do
      local g = row.gift
      if (g.kind == "mon" or g.kind == "egg") and g.shiny then
        local game = row.versions[1]
        for round = 1, 8 do
          local s = session(game)
          require("src.core.game3.rng").SeedRng(round * 7919)
          local list = MysteryGift.verifyFeed(Json.decode(FEEDS[family]), family, game)
          local entry
          for _, e in ipairs(list.cards) do if e.key == row.key then entry = e end end
          check(MysteryGift.receiveCard(s, entry.card), row.key .. " is saved")
          eq(MysteryGift.deliverGift(s, entry.card), MysteryGift.DELIVER_GIVEN, row.key .. " joins the party")
          eq(MysteryGift.deliverGift(s, entry.card), MysteryGift.DELIVER_ALREADY, row.key .. " only once")
          local mon = s.party[#s.party]
          eq(mon and mon.species, g.species, row.key .. " species")
          if round == 1 then
            if g.kind == "mon" then eq(mon.level, g.level, row.key .. " level") end
            if g.otName then eq(mon.otName, g.otName, row.key .. " OT " .. g.otName) end
            if g.otNames then
              local hit = false
              for _, n in ipairs(g.otNames) do if n == mon.otName then hit = true end end
              check(hit, row.key .. " OT is one of its choices: " .. tostring(mon.otName))
            end
            if g.otIdMax then check(mon.otId >= 1 and mon.otId <= g.otIdMax, row.key .. " TID rolled in range")
            elseif g.otId then eq(mon.otId, g.otId % 65536, row.key .. " TID") end
            if g.otId and not g.secretIdRandom then eq(mon.otSecretId, 0, row.key .. " SID 0") end
            if g.language then eq(mon.language, g.language, row.key .. " language") end
            if g.otGender == 0 or g.otGender == 1 then eq(mon.otGender, g.otGender, row.key .. " OT gender") end
            eq(mon.modernFatefulEncounter, g.fateful ~= false, row.key .. " fateful flag")
            if g.nationalRibbon then eq(Ribbons.get(mon, "national"), 1, row.key .. " National Ribbon") end
            if g.movesOnly then
              for slot = 1, 4 do eq(mon.moves[slot], g.moves[tostring(slot)], row.key .. " move " .. slot) end
            end
            if g.nickname then eq(mon.nickname, g.nickname, row.key .. " nickname") end
          end
          if g.shiny == "never" then check(shinyValue(mon) >= 8, row.key .. " is never shiny") end
          if g.shiny == "always" then check(shinyValue(mon) < 8, row.key .. " is always shiny") end
        end
      end
    end
  end
end

print("[test] 4. Every Ruby/Sapphire event passes the cart header on both games")
for _, game in ipairs({ "ruby", "sapphire" }) do
  local list = assert(MysteryGift.verifyFeed(Json.decode(FEED_RS), "rs", game))
  eq(#list.events, #raw("rs").events, "every rs event is listed on " .. game)
  for _, ev in ipairs(list.events) do
    check(MysteryGift.eventHeaderOk(ev.bytes, game), ev.key .. " passes me_checkcompat on " .. game)
  end
end

print("[test] 5. News reaches every game")
for family, games in pairs(FAMILY_GAMES) do
  for _, game in ipairs(games) do
    local list = MysteryGift.verifyFeed(Json.decode(FEEDS[family]), family, game)
    eq(list and #list.news, 1, "the news reaches " .. game)
  end
end

T.finish("game3_gift_catalog")
